.pdy-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pdy-root,.pdy-root *,.pdy-root *::before,.pdy-root *::after{box-sizing:border-box}
.pdy-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pdy-root img{display:block;border:0;max-width:none}
.pdy-root > [data-node-id]{will-change:transform}
.pdy-root [hidden]{display:none!important}
.pdy-root [data-sh-theme="dark"]{display:none!important}
.pdy-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.pdy-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.pdy-root .n3289_5492{background-color:var(--wa-bg, #f4f3f3);align-content:stretch;display:flex;gap:6px;height:25px;align-items:center;padding-left:5px;padding-right:5px;padding-top:2px;padding-bottom:2px;position:relative;border-radius:5px;flex-shrink:0;width:112px}
.pdy-root .n3289_5493{position:relative;flex-shrink:0;width:12px;height:12px}
.pdy-root .x7{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pdy-root .n3289_5495{word-break:break-word;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:520;line-height:15px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #303a46);font-size:14px;white-space:nowrap;width:7px}
.pdy-root [data-name^="Card/Stage"] p{letter-spacing:-0.05em;word-break:keep-all}
.pdy-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.pdy-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > div{background:linear-gradient(180deg,var(--wa-bg, #0d1117) 0%,var(--wa-bg, #111821) 100%)!important}
.pdy-root[data-theme="dark"] > [data-node-id] > div[aria-hidden] > img{opacity:.04!important;filter:invert(1)}
.pdy-root[data-theme="dark"] [data-name="Stage/3D Scene"] img{filter:brightness(.9) saturate(.95) contrast(1.03)}
.pdy-root[data-theme="dark"] [data-name="Stage/Building Image"] img{filter:brightness(.86) contrast(1.04)}
.pdy-root[data-theme="dark"] [data-name="Side Rail"],.pdy-root[data-theme="dark"] [data-name="Filter Panel"] [data-name="Rectangle 4"]{background:color-mix(in srgb, var(--wa-bg, rgb(20 23 29)) 84%, transparent)!important;box-shadow:0 0 0 1px rgba(255,255,255,.07),0 12px 28px rgba(0,0,0,.35)!important;-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.pdy-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Background"],.pdy-root[data-theme="dark"] > [data-node-id] > [data-name="Header"] > [data-name="Header Background"]{background:var(--wa-bg, #12151b)!important;box-shadow:inset 0 -1px 0 rgba(255,255,255,.07)!important}
.pdy-root[data-theme="dark"] svg [fill="#FCFCFC"]:not(mask *),.pdy-root[data-theme="dark"] svg [fill="#fcfcfc"]:not(mask *),.pdy-root[data-theme="dark"] svg [fill="white"]:not(mask *),.pdy-root[data-theme="dark"] svg [fill="#F9F9F9"]:not(mask *){fill:var(--wa-surface, #15181e)}
.pdy-root[data-theme="dark"] svg [stroke="#F1F1F1"]:not(mask *),.pdy-root[data-theme="dark"] svg [stroke="#f1f1f1"]:not(mask *),.pdy-root[data-theme="dark"] svg [fill="#F1F1F1"]:not(mask *){stroke:var(--wa-line, #2a2e36)}
.pdy-root[data-theme="dark"] svg path[fill="#F1F1F1"]:not(mask *){fill:var(--wa-surface, #2a2e36)}
.pdy-root[data-theme="dark"] [data-name="Event Log"] [data-name^="Row/"]:hover,.pdy-root[data-theme="dark"] [data-name="Event Log"] [data-name="grid-row"]:hover{filter:brightness(1.15)}
.pdy-root[data-theme="dark"] [data-name="Tooltip Group"] [data-name^="Tooltip/"] p{color:var(--wa-text, #e6ebf2)!important}
.pdy-root[data-theme="dark"] [data-name^="Category/"] img{content:normal!important}
.pdy-root[data-theme="dark"] .n3289_5492{background-color:var(--wa-surface, #20232a)}
.pdy-root[data-theme="dark"] .n3289_5495{color:var(--wa-text, #e6ebf2)}
